using System.IO;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace NexoLauncher.App.UI;

// Keep the technical type name stable while the product-facing brand is NEXA.
internal static class NexoBrandImage
{
    // Exact NEXA mark supplied by the project owner, resized only for UI delivery.
    private const string PngBase64 = "";

    public static ImageSource Create()
    {
        var bytes = Convert.FromBase64String(PngBase64);
        using var stream = new MemoryStream(bytes, writable: false);
        var image = new BitmapImage();
        image.BeginInit();
        image.CacheOption = BitmapCacheOption.OnLoad;
        image.CreateOptions = BitmapCreateOptions.PreservePixelFormat;
        image.StreamSource = stream;
        image.EndInit();
        image.Freeze();
        return image;
    }
}
